INSERT INTO feedback (id,target,shop_id,shop_name,rating,topic,message,name,contact,user_id,"timestamp",created_at) VALUES
('fb-seed-001','WEBSITE',NULL,NULL,5,'Trải nghiệm AR','Em muốn nhóm làm đồng hồ bám tay tốt hơn khi xoay cổ tay để việc so sánh và lựa chọn thuận tiện hơn.','Nguyễn Minh Anh','anhnmhe186355@fpt.edu.vn','u-seed-001','2026-06-20T08:13:29Z',1781943209000),
('fb-seed-002','WEBSITE',NULL,NULL,5,'Giao diện & nội dung','Mình muốn nhóm thêm nhiều mẫu dây da và dây kim loại để nội dung trưng bày đầy đủ hon.','Đỗ Trung Hiếu','hieudthe186637@fpt.edu.vn','u-seed-002','2026-06-16T02:26:58Z',1781576818000),
('fb-seed-003','WEBSITE',NULL,NULL,4,'Độ chính xác AR','Nhìn chung web ổn, nhưng trải nghiệm AR trên một vài góc nhìn chưa ổn và nên thêm chức năng so sánh hai mẫu đồng hồ.','Lê Hữu Nguyên','nguyenlhhe181804@fpt.edu.vn','u-seed-003','2026-06-19T09:39:27Z',1781861967000),
('fb-seed-004','WEBSITE',NULL,NULL,5,'Góp ý chung','Màu sắc website phù hợp với sản phẩm công nghệ nhưng em vẫn muốn nhóm tối ưu phần nhận diện cổ tay.','Nguyễn Cảnh Toàn','toannche186969@fpt.edu.vn','u-seed-004','2026-06-15T03:52:56Z',1781495576000),
('fb-seed-005','WEBSITE',NULL,NULL,2,'Tính năng so sánh','Tớ muốn nhóm bổ sung đồng hồ thông minh vào danh sách thử để website tạo cảm giác đáng tin hơn.','Cấn Thế Vinh','vinhcths180728@fpt.edu.vn','u-seed-005','2026-06-18T10:05:25Z',1781777125000),
('fb-seed-006','WEBSITE',NULL,NULL,5,'Hiệu năng & tốc độ','web có tiềm năng phát triển nhưng mình vẫn muốn nhóm thêm nhiều mẫu đồng hồ nam và nữ.','Nguyễn Thị Khánh Linh','linhntkhs180656@fpt.edu.vn','u-seed-006','2026-06-21T04:18:54Z',1782015534000),
('fb-seed-007','WEBSITE',NULL,NULL,4,'Trải nghiệm AR','Chị muốn nhóm làm cho chuyển động AR mượt hon để người dùng dễ chọn sản phẩm hon.','Nguyễn Thị Hương','huongnths181151@fpt.edu.vn','u-seed-007','2026-06-17T11:31:23Z',1781695883000),
('fb-seed-008','WEBSITE',NULL,NULL,5,'Giao diện & nội dung','Website có tiềm năng phát triển nhưng em vẫn muốn nhóm cho phép lưu mẫu đồng hồ yêu thích.','Mai Đức Hoàng','hoangmdhe180568@fpt.edu.vn','u-seed-008','2026-06-20T05:44:52Z',1781934292000),
('fb-seed-009','WEBSITE',NULL,NULL,3,'Độ chính xác AR','Mình muốn nhóm thêm nhiều mẫu dây da và dây kim loại để khả năng quyết định mua tốt hơn.','Đinh Khắc Quốc','quocdtse180045@fpt.edu.vn','u-seed-009','2026-06-16T12:57:21Z',1781614641000),
('fb-seed-010','WEBSITE',NULL,NULL,5,'Góp ý chung','Một số mẫu nhìn hơi giống nhau, nếu nhóm thêm gợi ý mẫu phù hợp vs phong cách người dùng thì anh sẽ thấy trải nghiệm tốt hơn.','Nguyễn Việt Anh','anhnvhe180220@fpt.edu.vn','u-seed-010','2026-06-19T06:10:50Z',1781849450000),
('fb-seed-011','WEBSITE',NULL,NULL,5,'Tính năng so sánh','Tính năng thử đồng hồ trên tay rất tiện, nhưng em muốn có thêm đồng hồ thông minh để thử.','Phan Thị Yến Thanh','thanhtyhe187226@fpt.edu.vn','u-seed-011','2026-06-15T13:23:19Z',1781529799000),
('fb-seed-012','WEBSITE',NULL,NULL,5,'Hiệu năng & tốc độ','Màu sắc website phù hợp vs sp công nghệ nhưng mình vẫn muốn nhóm thêm nhieu mẫu đồng hồ nam và nữ.','Lê Huy Thái','thailhe163306@fpt.edu.vn','u-seed-012','2026-06-18T07:36:48Z',1781768208000),
('fb-seed-013','WEBSITE',NULL,NULL,4,'Trải nghiệm AR','Anh thấy anh thấy cách thử đồng hồ trước khi mua rất hữu ích, chỉ cần nhóm bổ sung đồng hồ thông minh vào danh sách thử thì phần AR thuyết phục hơn.','Phạm Đình Đạt','datpdhe181334@fpt.edu.vn','u-seed-013','2026-06-21T01:49:17Z',1782006557000),
('fb-seed-014','WEBSITE',NULL,NULL,5,'Giao diện & nội dung','Trải nghiệm chọn đồng hồ khá mới lạ, nhưng thông tin từng mẫu đồng hồ còn hơi ngắn.','Bùi Hồng Việt','vietbhhe180460@fpt.edu.vn','u-seed-014','2026-06-17T08:02:46Z',1781683366000),
('fb-seed-015','WEBSITE',NULL,NULL,2,'Độ chính xác AR','Tớ thấy phần trình bày sp khá gọn gàng, chỉ cần nhóm thêm ảnh cận cảnh cho từng sp thì người dùng muốn quay lại trải nghiệm thêm.','Nguyễn Minh Đại','dainmhe187195@fpt.edu.vn','u-seed-015','2026-06-20T02:15:15Z',1781921715000),
('fb-seed-016','WEBSITE',NULL,NULL,5,'Góp ý chung','Mình thấy cách thử đồng hồ trước khi mua rất hữu ích và nếu nhóm hiển thị giá và thông số sản phẩm rõ hơn thì sản phẩm có giá trị trải nghiệm cao hơn.','Dương Đình Phú','phudthe187383@fpt.edu.vn','u-seed-016','2026-06-16T09:28:44Z',1781602124000),
