-- Seed 90 feedback users + their star-rating website feedback.
-- Source: danh_sach_gmail_phan_hoi_AR_watch.xlsx (first 90 rows).
-- Messages humanised: self-reference uses em/anh/chị/mình/tớ, with a few
-- abbreviations and no-diacritic typos. Spread across 2026-06-15..21; avg ~4.3.
--   psql "$DB_URL" -f db_export/seed_feedback_users.sql
BEGIN;

ON CONFLICT (email) DO NOTHING;

SELECT u.id,'CUSTOMER' FROM users u
WHERE u.id LIKE 'u-seed-%'
  AND NOT EXISTS (SELECT 1 FROM user_roles r WHERE r.user_id=u.id AND r.role='CUSTOMER');

ON CONFLICT (id) DO NOTHING;

COMMIT;